function size() {
  return this === undefined ? "none" : this.length;
}

const box = {
  length: 9,
  size,
  measure(fn) {
    return [fn(), arguments[0](), this.size()];
  },
};

console.log(box.measure(size, "a", "b").join(" "));

const list = [size, size];

console.log(list[0]());

const { measure } = box;

try {
  console.log(measure(size).join(" "));
} catch (error) {
  console.log(error.name);
}
